from scipy.ndimage import gaussian_filter1d,median_filter
from scipy.signal import find_peaks

def monotone(z,h):
    n=len(z)
    if n<3:return z
    turns=[0]; mode=0; hi=lo=0
    for j in range(1,n):
        if mode>=0 and z[j]>=z[hi]: hi=j
        if mode<=0 and z[j]<=z[lo]: lo=j
        if mode>=0 and z[hi]-z[j]>h:
            if hi>turns[-1]:turns.append(hi)
            mode=-1;lo=j
        elif mode<=0 and z[j]-z[lo]>h:
            if lo>turns[-1]:turns.append(lo)
            mode=1;hi=j
    if turns[-1]!=n-1:turns.append(n-1)
    y=z.copy()
    for a,b in zip(turns,turns[1:]):
        v=z[a:b+1]; s=1 if v[-1]>=v[0] else -1; v=v*s
        y[a:b+1]=s*(np.clip(np.maximum.accumulate(v),v[0],v[-1])+np.clip(np.minimum.accumulate(v[::-1])[::-1],v[0],v[-1]))*.5
    return y

def run_signal_processing(noisy_signal=None,window_size=20,signal_length=1000,noise_level=.3):
    if noisy_signal is None:
        t=np.linspace(0,10,signal_length); noisy_signal=np.sin(t)+np.random.default_rng(42).normal(0,noise_level,signal_length)
    x=np.asarray(noisy_signal,dtype=float).ravel();w=max(1,int(window_size))
    if len(x)<w:return {'filtered_signal':np.empty(0)}
    sigma=np.median(np.abs(np.diff(x,2)))/1.652 if len(x)>2 else 0
