    if not targets or num_partitions <= 0:
        for j in range(num_partitions):
            if src in dsts:
                topology.set_dst_partition_paths(src, j, [])
        return topology

    nodes = list(G)
    index = {v: i for i, v in enumerate(nodes)}
    root = index[src]
    terminals = [index[d] for d in targets]
    n = len(nodes)
    k = len(terminals)
    inf = float('inf')
    incoming = [[] for _ in nodes]
    weights = {}
    for x, y, data in G.edges(data=True):
        if x == y or y == src:
            continue
        try:
            w = float(data.get('cost', 1))
        except (ValueError, TypeError):
            continue
        if not math.isfinite(w) or w < 0:
            continue
        u, v = index[x], index[y]
        weights[u, v] = w
        incoming[v].append((u, w))

    def close(dist, choice, seeds):
        heap = [(dist[u], u) for u in seeds]
        heapq.heapify(heap)
        while heap:
            cost, v = heapq.heappop(heap)
            if cost != dist[v]:
                continue
            for u, w in incoming[v]:
                value = cost + w
                if value < dist[u]:
                    dist[u] = value
                    choice[u] = v
                    heapq.heappush(heap, (value, u))

    def reverse_paths(t):
        dist = [inf] * n
        nxt = [None] * n
        dist[t] = 0.0
        close(dist, nxt, [t])
        return dist, nxt

    routes = {t: reverse_paths(t) for t in terminals}
    for t in terminals:
        if routes[t][0][root] == inf:
            raise nx.NetworkXNoPath(f'No finite-cost route from {src} to {nodes[t]}')

    def path(parent, t):
        result = []
        while t != root:
            u = parent[t]
            result.append((u, t))
            t = u
        return result

    best = None
    best_cost = inf

    def consider(parent):
        nonlocal best, best_cost
        used = {}
        for t in terminals:
            while t != root and t not in used:
                u = parent[t]
                used[t] = u
                t = u
        cost = math.fsum(weights[u, v] for v, u in used.items())
        if cost < best_cost:
            best, best_cost = used, cost

    baseline = set()
    for t in terminals:
        nxt = routes[t][1]
        u = root
        while u != t:
            v = nxt[u]
            baseline.add((u, v))
            u = v

    def from_edges(edges):
        out = {}
        for u, v in sorted(edges):
            out.setdefault(u, []).append(v)
        parent = {root: None}
        queue = [root]
        for u in queue:
            for v in out.get(u, ()):
                if v not in parent:
                    parent[v] = u
                    queue.append(v)
        return parent

    consider(from_edges(baseline))
    exact = k <= 11 and n * 3 ** k <= 9000000 and len(weights) * (1 << k) <= 9000000
    if exact and best_cost > 0:
        end = (1 << k) - 1
        dp = [None] * (end + 1)
        decisions = [None] * (end + 1)
        for i, t in enumerate(terminals):
            dp[1 << i], decisions[1 << i] = routes[t]
        for mask in range(1, end + 1):
            if dp[mask] is not None:
                continue
            dist = [inf] * n
            choice = [None] * n
            anchor = mask & -mask
            rest = mask ^ anchor
            part = (rest - 1) & rest
            while True:
                a = part | anchor
                da, db = dp[a], dp[mask ^ a]
                marker = -a - 1
                for u, (ca, cb) in enumerate(zip(da, db)):
                    z = ca + cb
                    if z < dist[u]:
                        dist[u] = z
                        choice[u] = marker
                if not part:
                    break
                part = (part - 1) & rest
            close(dist, choice, [u for u in range(n) if dist[u] < inf])
            dp[mask], decisions[mask] = dist, choice
        edges = set()
        todo = [(root, end)]
        seen = set()
        while todo:
            u, mask = todo.pop()
            if (u, mask) in seen:
                continue
            seen.add((u, mask))
            v = decisions[mask][u]
            if v is None:
                continue
            if v < 0:
                a = -v - 1
                todo.extend(((u, a), (u, mask ^ a)))
            else:
                edges.add((u, v))
                todo.append((v, mask))
        consider(from_edges(edges))
    elif best_cost > 0:
        rng = random.Random(17103)
        scale = {t: routes[t][0][root] for t in terminals}

        def grow(seed=None, first=(), order=None, power=0, jitter=None):
            parent = {root: None}
            if seed:
                parent.update(seed)
            live = set(parent)
            source = {}
            remaining = set(terminals) - live
            for t in remaining:
                d = routes[t][0]
                a = min(live, key=lambda u: (d[u], u))
                source[t] = (d[a], a)

            def attach(t):
                if t in live:
                    return
                if t not in routes:
                    routes[t] = reverse_paths(t)
                d, nxt = routes[t]
                if t in source:
                    cost, a = source[t]
                else:
                    a = min(live, key=lambda u: (d[u], u))
                    cost = d[a]
                if cost == inf:
                    return
                chain = []
                while a != t:
                    b = nxt[a]
                    if b in live:
                        chain.clear()
                    else:
                        chain.append((a, b))
                    a = b
                for u, v in chain:
                    parent[v] = u
                    live.add(v)
                    remaining.discard(v)
                for p in remaining:
                    dd = routes[p][0]
                    cur = source[p]
                    for _, v in chain:
                        if dd[v] < cur[0]:
                            cur = (dd[v], v)
                    source[p] = cur

            for t in first:
                attach(t)
            if order is not None:
                for t in order:
                    attach(t)
            else:
                factors = {t: (scale[t] or 1.0) ** power * (jitter[t] if jitter else 1.0) for t in terminals}
                while remaining:
                    t = min(remaining, key=lambda p: (source[p][0] * factors[p], p))
                    attach(t)
            consider(parent)

        for power in (0, -0.5, -1, 0.5):
            grow(power=power)
        far = sorted(terminals, key=lambda t: (-scale[t], t))
        grow(order=far)
        grow(order=far[::-1])
        hubs = []
        for u in range(n):
            if u == root:
                continue
            gains = sorted((scale[t] - routes[t][0][u] for t in terminals if routes[t][0][u] < scale[t]), reverse=True)
            if gains:
                hubs.append((sum(gains), gains[0], u))
        # Price the trip to each prospective relay as well as its downstream savings.
        h = nx.DiGraph()
        h.add_nodes_from(range(n))
        h.add_weighted_edges_from((u, v, w) for (u, v), w in weights.items())
        forward = nx.single_source_dijkstra_path_length(h, root)
        ranked = sorted(((s - forward[u], peak - forward[u], u) for s, peak, u in hubs if u in forward), reverse=True)
        budget = max(10, min(72, 1600000 // max(1, n * k)))
        for _, _, u in ranked[:budget // 3]:
            grow(first=(u,))
            grow(first=(u,), power=-0.5)
        for t in far[:min(10, budget // 4)]:
            grow(first=(t,))
        for i in range(budget // 2):
            if i % 3 == 0:
                order = terminals[:]
                rng.shuffle(order)
                grow(order=order)
            else:
                grow(power=(-0.5 if i % 3 == 1 else 0), jitter={t: math.exp(rng.uniform(-1.6, 1.6)) for t in terminals})

        for _ in range(2):
            base = best.copy()
            term_paths = {t: path(base, t) for t in terminals}
            below = {}
            for t, edges in term_paths.items():
                for u, v in edges:
                    below.setdefault(v, set()).add(t)
            cuts = sorted(base, key=lambda v: (weights[base[v], v], len(below[v])), reverse=True)
            tried = set()
            for v in cuts:
                detached = frozenset(below[v])
                if detached in tried or len(detached) == k:
                    continue
                tried.add(detached)
                seed = {}
                for t in terminals:
                    if t not in detached:
                        seed.update((b, a) for a, b in term_paths[t])
                grow(seed=seed)
                if len(detached) > 1:
                    grow(seed=seed, order=far)
                if len(tried) >= budget // 3:
                    break
            if best == base:
                break

    for d in dict.fromkeys(dsts):
        t = index[d]
        edges = path(best, t)
        edges.reverse()
        for j in range(num_partitions):
            topology.set_dst_partition_paths(d, j, [[nodes[u], nodes[v], G[nodes[u]][nodes[v]]] for u, v in edges])
    return topology

def reorder(
    self,
    df: pd.DataFrame,
    early_stop: int = 0,
    row_stop: int = None,
    col_stop: int = None,
    col_merge: List[List[str]] = [],
    one_way_dep: List[Tuple[str, str]] = [],
    distinct_value_threshold: float = 0.8,
    parallel: bool = True,
) -> Tuple[pd.DataFrame, List[List[str]]]:
    import heapq
    import numpy as np
    from collections import Counter

    n, m = df.shape
    columns = df.columns.tolist()
    self.num_rows, self.num_cols = n, m
    if not n or not m:
        return df.copy(), [columns.copy() for _ in range(n)]
    values = df.astype(str).to_numpy(dtype=object)
    if n == 1:
        return pd.DataFrame(values, index=df.index, columns=df.columns), [columns]
    flat, vocabulary = pd.factorize(values.ravel(), sort=False)
    tokens = flat.reshape(n, m).tolist()
    weights = [len(s) ** 2 for s in vocabulary]
    support = [0] * len(weights)
    for row in tokens:
        for t in set(row):
            support[t] += 1
    rank = [(-w * (s - 1), -s, t) for t, (w, s) in enumerate(zip(weights, support))]
    base = range(m)

    def canonical(rows, tails):
        items = []
        for r in rows:
            cols = sorted(tails[r] if tails is not None else base, key=lambda c: rank[tokens[r][c]])
            items.append((tuple(tokens[r][c] for c in cols), r, cols))
        items.sort()
        return [(r, cols) for _, r, cols in items]

    def exact(rows, tails):
        k = len(rows)
        end = 1 << k
        common = [Counter() for _ in range(end)]
        for j, r in enumerate(rows):
            common[1 << j] = Counter(tokens[r][c] for c in tails[r])
        scores = [0] * end
        split = [0] * end
        for mask in range(1, end):
            bit = mask & -mask
            rem = mask ^ bit
            if rem:
                common[mask] = common[bit] & common[rem]
                best = -1
                sub = (rem - 1) & rem
                while True:
                    a = sub | bit
                    gain = scores[a] + scores[mask ^ a]
                    if gain > best:
                        best, split[mask] = gain, a
                    if not sub:
                        break
                    sub = (sub - 1) & rem
                scores[mask] = best + sum(weights[t] * qty for t, qty in common[mask].items())
        result = []

        def emit(mask, parent, prefix):
            a = split[mask]
            if a:
                added = tuple((common[mask] - common[parent]).elements())
                chain = prefix + added
                emit(a, mask, chain)
                emit(mask ^ a, mask, chain)
            else:
                r = rows[mask.bit_length() - 1]
                by_token = {}
                for c in reversed(tails[r]):
                    by_token.setdefault(tokens[r][c], []).append(c)
                cols = [by_token[t].pop() for t in prefix]
                used = set(cols)
                cols.extend(c for c in tails[r] if c not in used)
                result.append((r, cols))
        emit(end - 1, 0, ())
        return result

    def build(mode):
        tails = [list(base) for _ in range(n)]
        prefixes = [[] for _ in range(n)]
        result = []
        stack = [(list(range(n)), False)]
        budget = max(10000, 9 * n * m)
        exact_budget = 65000 if mode == 0 else 12000
        while stack:
            rows, leaf = stack.pop()
            width = len(tails[rows[0]])
            if leaf or len(rows) == 1 or not width:
                result.extend((r, prefixes[r] + tails[r]) for r in rows)
                continue
            k = len(rows)
            if k <= (11 if k == n else 7):
                cost = 3 ** k + (1 << k) * width
                if cost <= exact_budget or (k == n and cost <= 400000):
                    exact_budget -= cost
                    result.extend((r, prefixes[r] + cols) for r, cols in exact(rows, tails))
                    continue
            budget -= k * width
            if budget < 0:
                result.extend((r, prefixes[r] + cols) for r, cols in canonical(rows, tails))
                continue
            incidence = {}
            for r in rows:
                ts = tokens[r]
                for c in tails[r]:
                    t = ts[c]
                    if support[t] < 2:
                        continue
                    bucket = incidence.get(t)
                    if bucket is None:
                        incidence[t] = [r]
                    elif bucket[-1] != r:
                        bucket.append(r)
            grouped = {}
            for t, hits in incidence.items():
                if len(hits) > 1:
                    grouped.setdefault(tuple(hits), []).append(t)
            if not grouped:
                result.extend((r, prefixes[r] + tails[r]) for r in rows)
                continue
            hits_list = list(grouped)
            bundles = [sorted(grouped[h], key=rank.__getitem__) for h in hits_list]
            gains = [sum(weights[t] for t in bundle) for bundle in bundles]
            counts = list(map(len, hits_list))
            representatives = {bundle[0]: j for j, bundle in enumerate(bundles)}

            def entry(j):
                count = counts[j]
                if mode == 1:
                    priority = gains[j] * (count - 1) ** 0.55
                elif mode == 2:
                    priority = gains[j] * (count - 1) ** 1.45
                else:
                    priority = gains[j] * (count - 1)
                return (-priority, -count, j)

            heap = [entry(j) for j in range(len(counts))]
            heapq.heapify(heap)
            active = set(rows)
            children = []
            while heap and len(active) > 1:
                neg, size, j = heapq.heappop(heap)
                count = counts[j]
                if count != -size or count < 2:
                    continue
                if early_stop > 0 and gains[j] * (count - 1) < early_stop and mode == 0:
                    continue
                members = [r for r in hits_list[j] if r in active]
                active.difference_update(members)
                selected = {t: p for p, t in enumerate(bundles[j])}
                width_selected = len(selected)
                touched = set()
                update = len(active) > 1
                for r in members:
                    ts = tokens[r]
                    chosen = [-1] * width_selected
                    rest = []
                    affected = set()
                    for c in tails[r]:
                        t = ts[c]
                        p = selected.get(t)
                        if p is not None and chosen[p] == -1:
                            chosen[p] = c
                        else:
                            rest.append(c)
                        if update:
                            rep = representatives.get(t)
                            if rep is not None:
                                affected.add(rep)
                    for rep in affected:
                        counts[rep] -= 1
                    touched.update(affected)
                    tails[r] = rest
                    prefixes[r].extend(chosen)
                for rep in touched:
                    if counts[rep] > 1:
                        heapq.heappush(heap, entry(rep))
                children.append((members, False))
            if active:
                children.append(([r for r in rows if r in active], True))
            stack.extend(reversed(children))
        return result

    def score(order):
        prev = None
        total = 0
        for r, cols in order:
            cur = [tokens[r][c] for c in cols]
            if prev is not None:
                for a, b in zip(prev, cur):
                    if a != b:
                        break
                    total += weights[a]
            prev = cur
        return total

    best = build(0)
    if n > 11 or 3 ** n + (1 << n) * m > 400000:
        top = score(best)
        candidate = canonical(range(n), None)
        value = score(candidate)
        if value > top:
            best, top = candidate, value
        if n * m <= 350000:
            for mode in (1, 2) if n * m <= 85000 else (1,):
                candidate = build(mode)
                value = score(candidate)
                if value > top:
                    best, top = candidate, value
    row_ids = np.fromiter((r for r, _ in best), dtype=np.intp, count=n)
    positions = np.asarray([cols for _, cols in best], dtype=np.intp)
    reordered = pd.DataFrame(values[row_ids[:, None], positions], index=df.index.take(row_ids), columns=df.columns)
    return reordered, [[columns[c] for c in cols] for _, cols in best]

def compute_model_placement(gpu_num, models):
    import math
    import random

    models = list(models)
    n = len(models)
    if not n:
        return {b: [] for b in range(gpu_num)}
    if gpu_num <= 0:
        raise ValueError('No GPUs available')
    c = GPU_MEM_SIZE
    g = min(n, gpu_num)
    s = [m.model_size for m in models]
    w = [m.req_rate / m.slo for m in models]
    inf = float('inf')
    if max(s) > c or math.fsum(s) > g*c:
        raise ValueError('Insufficient GPU memory')

    def ratio(a, v):
        if a < c:
            return v / (c-a)
        return inf if v else 0.0

    if g == n:
        return {b: [models[b]] if b < n else [] for b in range(gpu_num)}
    ids = list(range(n))
    by_size = sorted(ids, key=lambda i: (s[i], w[i]), reverse=True)
    total_w = math.fsum(w)
    lower = max(max(ratio(s[i], w[i]) for i in ids), ratio(math.fsum(s)/g, total_w/g))
    scale = lower if 0 < lower < inf else max(w)/c
    rng = random.Random(71425)
    best = None
    upper = inf

    def measure(p):
        return max(ratio(sum(s[i] for i in q), sum(w[i] for i in q)) for q in p)

    def save(p):
        nonlocal best, upper
        if p is not None and all(sum(s[i] for i in q) <= c for q in p):
            value = measure(p)
            if best is None or value < upper:
                best, upper = p, value

    def greedy(order, eff, mode, limit=inf):
        ss = [0]*g
        ww = [0.0]*g
        ee = [0.0]*g
        p = [[] for _ in range(g)]
        for i in order:
            a, v, e = s[i], w[i], eff[i]
            b0 = -1
            k0 = (inf, inf)
            for b in range(g):
                aa, ee2 = ss[b]+a, ee[b]+e
                if aa > c or ee2 > limit:
                    continue
                if mode == 0:
                    k = (ratio(aa, ww[b]+v), ee2)
                elif mode == 1:
                    k = (ee2, aa)
                elif mode == 2:
                    k = (-ee2, -aa)
                else:
                    k = (ratio(ss[b], ww[b]), aa)
                if b0 < 0 or k < k0:
                    b0, k0 = b, k
                if mode == 1 and not p[b]:
                    break
            if b0 < 0:
                return None
            p[b0].append(i)
            ss[b0] += a
            ww[b0] += v
            ee[b0] += e
        return p

    # Fixed-threshold feasibility is ordinary packing of s[i]+w[i]/T.
    exact_budget = 0
    def pack(t, budget):
        nonlocal exact_budget
        e = s if t == inf else [s[i]+w[i]/t for i in ids]
        order = sorted(ids, key=lambda i: (e[i], s[i]), reverse=True)
        tol = 1e-10
        cap = c + tol
        if e[order[0]] > cap or math.fsum(e) > g*cap:
            return None, True
        # At most k large items of size strictly above capacity/(k+1) per bin.
        for k in range(1, min(16, (n-1)//g)+1):
            if e[order[k*g]] > cap/(k+1):
                return None, True
        for mode in (2, 1):
            p = greedy(order, e, mode, cap)
            if p is not None:
                return p, False
        budget = min(budget, exact_budget)
        if budget <= 0 or n > 220:
            return None, False
        remaining = budget
        loads = [0.0]*g
        sizes = [0]*g
        p = [[] for _ in range(g)]
        dead = set()

        def dfs(j, used):
            nonlocal remaining
            if j == n:
                return True
            if remaining <= 0:
                return False
            remaining -= 1
            key = (j, tuple(sorted((loads[b], sizes[b]) for b in range(used))))
            if key in dead:
                return False
            i = order[j]
            seen = set()
            for b in sorted(range(min(used+1, g)), key=loads.__getitem__, reverse=True):
                old = loads[b], sizes[b]
                if old in seen:
                    continue
                seen.add(old)
                v, a = old[0]+e[i], old[1]+s[i]
                if v > cap or a > c:
                    continue
                loads[b], sizes[b] = v, a
                p[b].append(i)
                if dfs(j+1, max(used,b+1)):
                    return True
                p[b].pop()
                loads[b], sizes[b] = old
                if remaining <= 0:
                    return False
            dead.add(key)
            return False

        ok = dfs(0, 0)
        exact_budget -= budget - remaining
        return (p if ok else None), not ok and remaining > 0

    def polish(p, steps, exchanges=False):
        p = [q[:] for q in p]
        ss = [sum(s[i] for i in q) for q in p]
        ww = [sum(w[i] for i in q) for q in p]
        rr = [ratio(a,v) for a,v in zip(ss,ww)]
        for _ in range(steps):
            top = max(rr)
            if top == 0:
                break
            change = None
            merit = (0.0, 0.0)
            for a in sorted(range(g), key=rr.__getitem__, reverse=True)[:3]:
                if rr[a] < top:
                    break
                for b in range(g):
                    if b == a:
                        continue
                    old_low = min(rr[a], rr[b])
                    candidates = [((), (j,), -s[j], -w[j]) for j in p[b]]
                    candidates.append(((), (), 0, 0.0))
                    # Also try exchanging two destination models for one bottleneck model.
                    if exchanges and len(p[b]) <= 11:
                        for u, j in enumerate(p[b]):
                            for k in p[b][u+1:]:
                                candidates.append(((), (j,k), -s[j]-s[k], -w[j]-w[k]))
                    for i in p[a]:
                        for _, js, ds, dw in candidates:
                            d, v = s[i]+ds, w[i]+dw
                            sa, sb = ss[a]-d, ss[b]+d
                            if sa > c or sb > c:
                                continue
                            x = ratio(sa, ww[a]-v)
                            y = ratio(sb, ww[b]+v)
                            hi, lo = max(x,y), min(x,y)
                            if hi < top:
                                gain = ((top-hi) if top < inf else inf, -lo)
                            elif hi == top and lo < old_low:
                                gain = (0.0, (old_low-lo) if old_low < inf else inf)
                            else:
                                continue
                            if change is None or gain > merit:
                                merit = gain
                                change = a,b,i,js
            if change is None:
                break
            a,b,i,js = change
            p[a].remove(i)
            for j in js:
                p[b].remove(j)
            p[a].extend(js)
            p[b].append(i)
            for k in (a,b):
                ss[k] = sum(s[i] for i in p[k])
                ww[k] = sum(w[i] for i in p[k])
                rr[k] = ratio(ss[k],ww[k])
        return p

    local_steps = min(70, max(6, 48000//max(1,n*g)))
    trials = []
    def try_order(order, e, mode):
        p = greedy(order, e, mode)
        if p is not None:
            trials.append((measure(p),p))
            save(p)

    try_order(by_size, s, 2)
    by_w = sorted(ids, key=lambda i: w[i], reverse=True)
    try_order(by_w, s, 3)
    try_order(by_w, s, 0)
    try_order(sorted(ids,key=lambda i:ratio(s[i],w[i]),reverse=True), s, 0)
    if scale > 0:
        for f in (0.35, 0.75, 1.0, 2.0, 6.0):
            e = [s[i]+w[i]/(scale*f) for i in ids]
            order = sorted(ids, key=e.__getitem__, reverse=True)
            for mode in (0, 1, 2):
                try_order(order, e, mode)
        e = [s[i]+w[i]/scale for i in ids]
        for j in range(10 if n*g <= 30000 else 4):
            order = sorted(ids, key=lambda i: e[i]*(1+rng.uniform(-0.24,0.24)), reverse=True)
            try_order(order, e, j%3)
    for _, p in sorted(trials, key=lambda z:z[0])[:5]:
        save(polish(p, local_steps))
    if best is None:
        exact_budget = 65000 if n <= 100 else 22000
        p, _ = pack(inf, exact_budget)
        save(p)
        if best is None:
            raise ValueError('Unable to place all models within GPU memory')

    if upper > 0 and upper < inf and lower < upper:
        # Keep proven lower bounds separate from heuristic search failures.
        lo = max(0.0, lower)
        proven = lo
        exact_budget = 33000 if n <= 55 else (9000 if n <= 105 else 0)
        for j in range(15):
            if upper-lo <= 2e-7*upper:
                break
            t = (lo+upper)*0.5
            p, impossible = pack(t, 6000 if n <= 55 else 1800)
            if p is not None:
                prev = upper
                save(p)
                if j < 7:
                    save(polish(p, local_steps//2+1))
                if prev == upper:
                    lo = t
                elif upper < lo:
                    lo = proven
            else:
                lo = t
                if impossible:
                    proven = t
    if upper > 0:
        save(polish(best, local_steps, n <= 240 and n*g <= 13000))
    return {b: [models[i] for i in best[b]] if b < g else [] for b in range(gpu_num)}
